using System.Buffers.Binary;
using System.Security.Cryptography;

namespace Zenith.Protocol.ZenFabric;

/// <summary>
/// Framing and encryption of a ZenFabric message inside a LiteNetLib message.
///
///  LiteNetLib payload (DeliveryMethod.ReliableOrdered, channel 0):
///     [int32 PayloadLength (plain text, little endian)] [Payload]
///  Payload = [int32 OpCode][Body], XOR-encrypted if a key is set:
///     payload[i] ^= key[i % key.Length]     (index restarts at 0 for EVERY message)
///
///  The key (2048 random bytes) is generated by the client and sent to the server via RSA (PKCS#1 v1.5,
///  in 245-byte blocks) using the public key from ProtocolSettings.
///  Encryption is active once the client has sent AuthWorker (client side) or
///  the server has received AuthWorker (server side).
/// </summary>
public static class ZfCodec
{
    public const int SymmetricKeyLength = 2048;
    public const int RsaChunkSize = 245; // 2048-bit RSA with PKCS#1 v1.5 => max. 245 bytes of plain text

    public static void Xor(Span<byte> data, ReadOnlySpan<byte> key)
    {
        if (key.IsEmpty) return;
        for (var i = 0; i < data.Length; i++)
            data[i] ^= key[i % key.Length];
    }

    /// <summary>Builds the LiteNetLib payload for an operation.</summary>
    public static byte[] Frame(ZfOp op, byte[]? key) => FramePayload(op.Serialize(), key);

    /// <summary>Frames a plain-text payload (and encrypts it if key != null).</summary>
    public static byte[] FramePayload(ReadOnlySpan<byte> payload, byte[]? key)
    {
        var buf = new byte[4 + payload.Length];
        BinaryPrimitives.WriteInt32LittleEndian(buf, payload.Length);
        payload.CopyTo(buf.AsSpan(4));
        if (key is not null) Xor(buf.AsSpan(4), key);
        return buf;
    }

    /// <summary>Reads [int32 len][payload] from a LiteNetLib message and decrypts it if needed.</summary>
    public static byte[] Unframe(ReadOnlySpan<byte> lnlData, byte[]? key)
    {
        if (lnlData.Length < 4) throw new InvalidDataException("ZenFabric frame too short");
        var len = BinaryPrimitives.ReadInt32LittleEndian(lnlData);
        if (len < 0 || len > lnlData.Length - 4)
            throw new InvalidDataException($"Invalid ZenFabric length {len} (available {lnlData.Length - 4})");
        var payload = lnlData.Slice(4, len).ToArray();
        if (key is not null) Xor(payload, key);
        return payload;
    }

    public static byte[] NewSymmetricKey() => RandomNumberGenerator.GetBytes(SymmetricKeyLength);

    /// <summary>Client side: encrypt the key in 245-byte blocks with RSA-PKCS1.</summary>
    public static List<byte[]> EncryptSymmetricKey(byte[] key, byte[] modulus, byte[] exponent)
    {
        using var rsa = RSA.Create();
        rsa.ImportParameters(new RSAParameters { Modulus = modulus, Exponent = exponent });
        var parts = new List<byte[]>();
        for (var off = 0; off < key.Length; off += RsaChunkSize)
        {
            var n = Math.Min(RsaChunkSize, key.Length - off);
            parts.Add(rsa.Encrypt(key.AsSpan(off, n).ToArray(), RSAEncryptionPadding.Pkcs1));
        }
        return parts;
    }

    /// <summary>Server side: decrypt the blocks and join them.</summary>
    public static byte[] DecryptSymmetricKey(IEnumerable<byte[]> parts, RSA rsa)
    {
        using var ms = new MemoryStream();
        foreach (var p in parts)
            ms.Write(rsa.Decrypt(p, RSAEncryptionPadding.Pkcs1));
        return ms.ToArray();
    }

    /// <summary>Loads or creates a 2048-bit RSA key (PEM).</summary>
    public static RSA LoadOrCreateRsa(string pemPath)
    {
        var rsa = RSA.Create(2048);
        if (File.Exists(pemPath))
        {
            rsa.ImportFromPem(File.ReadAllText(pemPath));
            return rsa;
        }
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(pemPath))!);
        File.WriteAllText(pemPath, rsa.ExportRSAPrivateKeyPem());
        return rsa;
    }

    public static ProtocolSettingsOp MakeProtocolSettings(RSA rsa)
    {
        var p = rsa.ExportParameters(false);
        return new ProtocolSettingsOp { Modulus = p.Modulus!, Exponent = p.Exponent! };
    }
}
